xswap-fast-in-v1.patch:
diff --git a/mm/memory.c b/mm/memory.c
index 6fd925877..514fc778a 100644
--- a/mm/memory.c
+++ b/mm/memory.c
@@ -4991,23 +4991,15 @@ vm_fault_t do_swap_page(struct vm_fault *vmf)
 		goto out;
 	}

-	folio = swap_cache_get_folio(entry);
-	if (folio)
-		swap_update_readahead(folio, vma, vmf->address);
-	if (!folio) {
-		/* Swapin bypasses readahead for SWP_SYNCHRONOUS_IO devices */
-		if (data_race(si->flags & SWP_SYNCHRONOUS_IO))
-			folio = swapin_sync(entry, GFP_HIGHUSER_MOVABLE,
-					    thp_swapin_suitable_orders(vmf) | BIT(0),
-					    vmf, NULL, 0);
-		else
-			folio = swapin_readahead(entry, GFP_HIGHUSER_MOVABLE, vmf);
-
+	/*
+	 * Synchronous swap devices bypass readahead and preliminary cache lookups;
+	 * enter the allocator-first synchronous swapin path directly.
+	 */
+	if (data_race(si->flags & SWP_SYNCHRONOUS_IO)) {
+		folio = swapin_sync(entry, GFP_HIGHUSER_MOVABLE,
+				    thp_swapin_suitable_orders(vmf) | BIT(0),
+				    vmf, NULL, 0);
 		if (IS_ERR_OR_NULL(folio)) {
-			/*
-			 * Back out if somebody else faulted in this pte
-			 * while we released the pte lock.
-			 */
 			vmf->pte = pte_offset_map_lock(vma->vm_mm, vmf->pmd,
 					vmf->address, &vmf->ptl);
 			if (likely(vmf->pte &&
@@ -5016,11 +5008,28 @@ vm_fault_t do_swap_page(struct vm_fault *vmf)
 			folio = NULL;
 			goto unlock;
 		}
-
-		/* Had to read the page from swap area: Major fault */
 		ret = VM_FAULT_MAJOR;
 		count_vm_event(PGMAJFAULT);
 		count_memcg_event_mm(vma->vm_mm, PGMAJFAULT);
+	} else {
+		folio = swap_cache_get_folio(entry);
+		if (folio)
+			swap_update_readahead(folio, vma, vmf->address);
+		if (!folio) {
+			folio = swapin_readahead(entry, GFP_HIGHUSER_MOVABLE, vmf);
+			if (IS_ERR_OR_NULL(folio)) {
+				vmf->pte = pte_offset_map_lock(vma->vm_mm, vmf->pmd,
+						vmf->address, &vmf->ptl);
+				if (likely(vmf->pte &&
+					   pte_same(ptep_get(vmf->pte), vmf->orig_pte)))
+					ret = VM_FAULT_OOM;
+				folio = NULL;
+				goto unlock;
+			}
+			ret = VM_FAULT_MAJOR;
+			count_vm_event(PGMAJFAULT);
+			count_memcg_event_mm(vma->vm_mm, PGMAJFAULT);
+		}
 	}

 	swapcache = folio;
diff --git a/mm/swap_state.c b/mm/swap_state.c
index 7ac1808ae..280b98725 100644
--- a/mm/swap_state.c
+++ b/mm/swap_state.c
@@ -24,6 +24,8 @@
 #include <linux/shmem_fs.h>
 #include <linux/sysctl.h>
 #include <linux/swap_ops.h>
+#include <linux/workqueue.h>
+#include <linux/zswap.h>
 #include "internal.h"
 #include "swap_table.h"
 #include "swap.h"
@@ -65,9 +67,9 @@ static bool enable_vma_readahead __read_mostly = true;
 	 (((win) << SWAP_RA_WIN_SHIFT) & SWAP_RA_WIN_MASK) |	\
 	 ((hits) & SWAP_RA_HITS_MASK))

-/* Initial readahead hits is 4 to start up with a small window */
+/* Do not seed initial hits; require contiguous access to grow window */
 #define GET_SWAP_RA_VAL(vma)					\
-	(atomic_long_read(&(vma)->swap_readahead_info) ? : 4)
+	atomic_long_read(&(vma)->swap_readahead_info)

 static atomic_t swapin_readahead_hits = ATOMIC_INIT(4);

@@ -457,18 +459,16 @@ static struct folio *__swap_cache_alloc(struct swap_info_struct *si,
 	VM_WARN_ON_ONCE(nr_pages > SWAPFILE_CLUSTER);
 	entry.val = round_down(targ_entry.val, nr_pages);

-	/*
-	 * Check if the slot and range are available, skip allocation if not.
-	 * Nothing pins the slot yet, so look its cluster up each time: it
-	 * may be freed, and on xswap unmapped, while the folio is allocated.
-	 */
-	ci = swap_cluster_lock_unpinned(si, swp_offset(targ_entry));
-	if (unlikely(!ci))
-		return ERR_PTR(-ENOENT);
-	err = __swap_cache_add_check(ci, targ_entry, nr_pages, NULL, NULL);
-	spin_unlock(&ci->lock);
-	if (unlikely(err))
-		return ERR_PTR(err);
+	/* Avoid wasting large or speculative allocations on unavailable slots. */
+	if (order || !vmf) {
+		ci = swap_cluster_lock_unpinned(si, swp_offset(targ_entry));
+		if (unlikely(!ci))
+			return ERR_PTR(-ENOENT);
+		err = __swap_cache_add_check(ci, targ_entry, nr_pages, NULL, NULL);
+		spin_unlock(&ci->lock);
+		if (unlikely(err))
+			return ERR_PTR(err);
+	}

 	/*
 	 * Limit THP gfp. The limitation is a no-op for typical
@@ -709,13 +709,26 @@ void swap_update_readahead(struct folio *folio, struct vm_area_struct *vma,
 	readahead = folio_test_clear_readahead(folio);
 	if (vma && vma_ra) {
 		unsigned long ra_val;
+		unsigned long prev_addr;
 		int win, hits;
+		bool is_contiguous;

 		ra_val = GET_SWAP_RA_VAL(vma);
+		prev_addr = SWAP_RA_ADDR(ra_val);
 		win = SWAP_RA_WIN(ra_val);
 		hits = SWAP_RA_HITS(ra_val);
-		if (readahead)
+
+		is_contiguous = prev_addr &&
+			(addr == prev_addr + PAGE_SIZE ||
+			 prev_addr == addr + PAGE_SIZE);
+
+		if (!is_contiguous) {
+			hits = 0;
+			win = 1;
+		} else if (readahead) {
 			hits = min_t(int, hits + 1, SWAP_RA_HITS_MAX);
+		}
+
 		atomic_long_set(&vma->swap_readahead_info,
 				SWAP_RA_VAL(addr, win, hits));
 	}
@@ -775,12 +788,16 @@ struct folio *swapin_sync(swp_entry_t entry, gfp_t gfp, unsigned long orders,
 	struct swap_io_ctx ctx = {};
 	struct folio *folio;

-	do {
+	/* Callers already missed the cache; let the allocator check races. */
+	for (;;) {
+		folio = __swap_cache_alloc_folio(entry, gfp, orders, vmf, mpol, ilx);
+		if (PTR_ERR(folio) != -EEXIST)
+			break;
+
 		folio = swap_cache_get_folio(entry);
 		if (folio)
 			return folio;
-		folio = __swap_cache_alloc_folio(entry, gfp, orders, vmf, mpol, ilx);
-	} while (PTR_ERR(folio) == -EEXIST);
+	}

 	if (IS_ERR(folio))
 		return folio;
@@ -836,6 +853,13 @@ static unsigned int __swapin_nr_pages(unsigned long prev_offset,
 {
 	unsigned int pages, last_ra;

+	/*
+	 * Immediate collapse on stride disruption or non-contiguous access:
+	 * do not retain prior window across non-adjacent offsets.
+	 */
+	if (prev_offset && offset != prev_offset + 1 && offset != prev_offset - 1)
+		return 1;
+
 	/*
 	 * This heuristic has been found to work well on both sequential and
 	 * random loads, swapping to hard disk or to SSD: please don't ask
@@ -889,6 +913,66 @@ static unsigned long swapin_nr_pages(unsigned long offset)
 	return pages;
 }

+#define ZSWAP_PREFETCH_BATCH 32
+
+struct zswap_prefetch_batch {
+	struct work_struct work;
+	unsigned int nr;
+	swp_entry_t entries[ZSWAP_PREFETCH_BATCH];
+};
+
+static struct workqueue_struct *zswap_prefetch_wq;
+
+static void zswap_prefetch_work_fn(struct work_struct *work)
+{
+	struct zswap_prefetch_batch *batch =
+		container_of(work, struct zswap_prefetch_batch, work);
+	unsigned int i;
+
+	for (i = 0; i < batch->nr; i++) {
+		swp_entry_t entry = batch->entries[i];
+		struct swap_info_struct *si;
+		struct folio *folio;
+		int ret;
+
+		si = get_swap_device(entry);
+		if (IS_ERR_OR_NULL(si))
+			continue;
+
+		folio = swap_cache_get_folio(entry);
+		if (folio) {
+			folio_put(folio);
+			put_swap_device(si);
+			continue;
+		}
+
+		folio = __swap_cache_alloc_folio(entry,
+						 GFP_NOWAIT | __GFP_NOWARN | __GFP_NORETRY,
+						 BIT(0), NULL, NULL, 0);
+		if (IS_ERR_OR_NULL(folio)) {
+			put_swap_device(si);
+			continue;
+		}
+
+		ret = zswap_load(folio);
+		if (ret == 0) {
+			folio_add_lru(folio);
+			folio_set_readahead(folio);
+			count_vm_event(SWAP_RA);
+		} else {
+			if (!folio_test_locked(folio))
+				folio_lock(folio);
+			swap_cache_del_folio(folio);
+			folio_unlock(folio);
+		}
+
+		folio_put(folio);
+		put_swap_device(si);
+	}
+
+	kfree(batch);
+}
+
 /**
  * swap_cluster_readahead - swap in pages in hope we need them soon
  * @entry: swap entry of this memory
@@ -920,9 +1004,9 @@ struct folio *swap_cluster_readahead(swp_entry_t entry, gfp_t gfp_mask,
 	struct blk_plug plug;
 	swp_entry_t ra_entry;

-	/* xswap entries live only in zswap; readahead does not help. */
-	if (si->flags & SWP_XSWAP)
-		goto skip;
+	bool zswap_active;
+
+	zswap_active = zswap_is_enabled() || (si->flags & SWP_XSWAP);

 	mask = swapin_nr_pages(offset) - 1;
 	if (!mask)
@@ -936,6 +1020,28 @@ struct folio *swap_cluster_readahead(swp_entry_t entry, gfp_t gfp_mask,
 	if (end_offset >= si->max)
 		end_offset = si->max - 1;

+	if (zswap_active) {
+		struct zswap_prefetch_batch *batch;
+
+		batch = kmalloc_obj(*batch, GFP_NOWAIT | __GFP_NOWARN);
+		if (batch) {
+			INIT_WORK(&batch->work, zswap_prefetch_work_fn);
+			batch->nr = 0;
+			for (offset = start_offset; offset <= end_offset; offset++) {
+				if (offset == entry_offset)
+					continue;
+				ra_entry = swp_entry(swp_type(entry), offset);
+				if (batch->nr < ZSWAP_PREFETCH_BATCH)
+					batch->entries[batch->nr++] = ra_entry;
+			}
+			if (batch->nr > 0 && zswap_prefetch_wq)
+				queue_work(zswap_prefetch_wq, &batch->work);
+			else
+				kfree(batch);
+		}
+		return swap_cache_read_folio_sync(entry, gfp_mask, mpol, ilx);
+	}
+
 	blk_start_plug(&plug);
 	for (offset = start_offset; offset <= end_offset ; offset++) {
 		/* Ok, do the async read-ahead now */
@@ -959,6 +1065,7 @@ static int swap_vma_ra_win(struct vm_fault *vmf, unsigned long *start,
 	unsigned long ra_val;
 	unsigned long faddr, prev_faddr, left, right;
 	unsigned int max_win, hits, prev_win, win;
+	bool is_contiguous;

 	max_win = 1 << min(READ_ONCE(page_cluster), SWAP_RA_ORDER_CEILING);
 	if (max_win == 1)
@@ -969,9 +1076,41 @@ static int swap_vma_ra_win(struct vm_fault *vmf, unsigned long *start,
 	prev_faddr = SWAP_RA_ADDR(ra_val);
 	prev_win = SWAP_RA_WIN(ra_val);
 	hits = SWAP_RA_HITS(ra_val);
+
+	/*
+	 * Stride gating: check if access is contiguous with previous fault.
+	 */
+	is_contiguous = prev_faddr &&
+		(faddr == prev_faddr + PAGE_SIZE || prev_faddr == faddr + PAGE_SIZE);
+
+	if (!is_contiguous) {
+		/*
+		 * Immediate collapse on stride disruption or random access:
+		 * Reset streak to 0 and clamp window to 1.
+		 */
+		atomic_long_set(&vma->swap_readahead_info,
+				SWAP_RA_VAL(faddr, 1, 0));
+		return 1;
+	}
+
+	/* Contiguous hit: advance streak */
+	hits = min_t(unsigned int, hits + 1, SWAP_RA_HITS_MAX);
+
+	/*
+	 * Require 2+ contiguous hits before expanding window beyond 1.
+	 */
+	if (hits < 2) {
+		atomic_long_set(&vma->swap_readahead_info,
+				SWAP_RA_VAL(faddr, 1, hits));
+		return 1;
+	}
+
 	win = __swapin_nr_pages(PFN_DOWN(prev_faddr), PFN_DOWN(faddr), hits,
 				max_win, prev_win);
-	atomic_long_set(&vma->swap_readahead_info, SWAP_RA_VAL(faddr, win, 0));
+	if (win < 2)
+		win = 2;
+
+	atomic_long_set(&vma->swap_readahead_info, SWAP_RA_VAL(faddr, win, hits));
 	if (win == 1)
 		return 1;

@@ -1018,14 +1157,63 @@ static struct folio *swap_vma_readahead(swp_entry_t targ_entry, gfp_t gfp_mask,
 	unsigned long start, end, addr;
 	pgoff_t ilx = targ_ilx;

-	/* xswap entries live only in zswap; readahead does not help. */
-	if (si->flags & SWP_XSWAP)
-		goto skip;
+	bool zswap_active;
+
+	zswap_active = zswap_is_enabled() || (si->flags & SWP_XSWAP);

 	win = swap_vma_ra_win(vmf, &start, &end);
 	if (win == 1)
 		goto skip;

+	if (zswap_active) {
+		struct zswap_prefetch_batch *batch;
+
+		batch = kmalloc_obj(*batch, GFP_NOWAIT | __GFP_NOWARN);
+		if (batch) {
+			INIT_WORK(&batch->work, zswap_prefetch_work_fn);
+			batch->nr = 0;
+		}
+
+		for (addr = start; addr < end; addr += PAGE_SIZE) {
+			softleaf_t entry;
+
+			if (addr == vmf->address) {
+				if (pte) {
+					pte_unmap(pte);
+					pte = NULL;
+				}
+				continue;
+			}
+
+			if (!pte) {
+				pte = pte_offset_map(vmf->pmd, addr);
+				if (!pte)
+					break;
+			} else {
+				pte++;
+			}
+			pentry = ptep_get_lockless(pte);
+			entry = softleaf_from_pte(pentry);
+
+			if (!softleaf_is_swap(entry))
+				continue;
+
+			if (batch && batch->nr < ZSWAP_PREFETCH_BATCH)
+				batch->entries[batch->nr++] = entry;
+		}
+		if (pte)
+			pte_unmap(pte);
+
+		if (batch) {
+			if (batch->nr > 0 && zswap_prefetch_wq)
+				queue_work(zswap_prefetch_wq, &batch->work);
+			else
+				kfree(batch);
+		}
+
+		return swap_cache_read_folio_sync(targ_entry, gfp_mask, mpol, targ_ilx);
+	}
+
 	ilx = targ_ilx - PFN_DOWN(vmf->address - start);

 	blk_start_plug(&plug);
@@ -1115,6 +1303,9 @@ static void __init swap_readahead_setup(void)
 {
 	unsigned long megs = PAGES_TO_MB(totalram_pages());

+	zswap_prefetch_wq = alloc_workqueue("zswap-prefetch",
+					    WQ_UNBOUND | WQ_MEM_RECLAIM, 0);
+
 	/* Use a smaller cluster for small-memory machines */
 	if (megs < 16)
 		page_cluster = 2;
